import os, re, subprocess, collections

root = "/bench/repo"
gofiles = []
for dp, dn, fn in os.walk(root):
    if any(p in dp for p in ("/.git", "/web", "/node_modules")):
        continue
    for f in fn:
        if f.endswith(".go"):
            gofiles.append(os.path.join(dp, f))

# read all files once
content = {}
for f in gofiles:
    try:
        content[f] = open(f, encoding="utf-8", errors="ignore").read()
    except Exception:
        pass

decl_re = re.compile(r'^func\s+(?:\((?P<recv>[^)]*)\)\s+)?(?P<name>[A-Za-z_]\w*)\s*(?:\[[^\]]*\])?\(', re.M)

decls = []  # (name, path, line, is_method, pkgdir)
for f in sorted(content):
    if not f.startswith(os.path.join(root, "internal")):
        continue
    if f.endswith("_test.go"):
        continue
    txt = content[f]
    for m in decl_re.finditer(txt):
        line = txt[:m.start()].count("\n") + 1
        decls.append((m.group("name"), f, line, bool(m.group("recv")), os.path.dirname(f)))

# package name per dir
pkgname = {}
for f in content:
    m = re.search(r'^package\s+(\w+)', content[f], re.M)
    if m:
        pkgname.setdefault(os.path.dirname(f), m.group(1))

results = []
for name, f, line, is_method, pkgdir in decls:
    pkg = pkgname.get(pkgdir, "")
    total = 0
    external = 0
    callers = collections.Counter()
    if is_method:
        pat = re.compile(r'\.' + re.escape(name) + r'\s*\(')
    else:
        pat = None
    for g, txt in content.items():
        if pat is not None:
            hits = len(pat.findall(txt))
        else:
            # same package: bare call; other packages: pkg.Name(
            same_pkg = os.path.dirname(g) == pkgdir
            if same_pkg:
                hits = len(re.findall(r'(?<![\w.])' + re.escape(name) + r'\s*\(', txt))
                # subtract declaration itself
                hits -= len(re.findall(r'^func\s+' + re.escape(name) + r'\s*(?:\[[^\]]*\])?\(', txt, re.M))
                if hits < 0: hits = 0
            else:
                hits = len(re.findall(r'(?<![\w.])' + re.escape(pkg) + r'\.' + re.escape(name) + r'\s*\(', txt))
        if hits:
            total += hits
            callers[g] = hits
            if os.path.dirname(g) != pkgdir:
                external += hits
    results.append((total, external, name, f, line, is_method, callers))

results.sort(key=lambda r: -r[0])
for total, external, name, f, line, is_method, callers in results[:25]:
    rel = os.path.relpath(f, root)
    kind = "method" if is_method else "func"
    print(f"{total:5d} tot {external:5d} ext  {kind:6s} {name:35s} {rel}:{line}")
EOF
