cd /bench/repo && cat > /tmp/fanin.pl <<'EOF'
use strict; use warnings;
use File::Find;
my $root = "/bench/repo";
my @gofiles;
find(sub {
  return unless -f $_ && /\.go$/;
  my $p = $File::Find::name;
  return if $p =~ m{/\.git/|/web/|/node_modules/};
  push @gofiles, $p;
}, $root);

my %content;
for my $f (@gofiles) {
  open my $fh, '<', $f or next;
  local $/; my $t = <$fh>; close $fh;
  $content{$f} = $t;
}

my %pkgname;
for my $f (keys %content) {
  my ($dir) = $f =~ m{^(.*)/[^/]+$};
  if (!exists $pkgname{$dir} && $content{$f} =~ /^package\s+(\w+)/m) { $pkgname{$dir} = $1; }
}

my @decls;
for my $f (sort keys %content) {
  next unless $f =~ m{^\Q$root\E/internal/};
  next if $f =~ /_test\.go$/;
  my $t = $content{$f};
  my @lines = split /\n/, $t, -1;
  for my $i (0..$#lines) {
    my $l = $lines[$i];
    if ($l =~ /^func\s+(?:\(([^)]*)\)\s+)?([A-Za-z_]\w*)\s*(?:\[[^\]]*\])?\(/) {
      my ($recv,$name) = ($1,$2);
      my ($dir) = $f =~ m{^(.*)/[^/]+$};
      push @decls, { name=>$name, file=>$f, line=>$i+1, method=>(defined $recv ? 1:0), dir=>$dir };
    }
  }
}

my @res;
for my $d (@decls) {
  my $name = $d->{name}; my $dir = $d->{dir};
  my $pkg = $pkgname{$dir} // '';
  my ($tot,$ext) = (0,0);
  my %by;
  for my $g (keys %content) {
    my $t = $content{$g};
    my ($gdir) = $g =~ m{^(.*)/[^/]+$};
    my $hits = 0;
    if ($d->{method}) {
      $hits = () = $t =~ /\.\Q$name\E\s*\(/g;
    } else {
      if ($gdir eq $dir) {
        $hits = () = $t =~ /(?<![\w.])\Q$name\E\s*\(/g;
        my $dcl = () = $t =~ /^func\s+\Q$name\E\s*(?:\[[^\]]*\])?\(/mg;
        $hits -= $dcl; $hits = 0 if $hits < 0;
      } else {
        $hits = () = $t =~ /(?<![\w.])\Q$pkg\E\.\Q$name\E\s*\(/g;
      }
    }
    if ($hits > 0) { $tot += $hits; $by{$g} = $hits; $ext += $hits if $gdir ne $dir; }
  }
  push @res, { %$d, tot=>$tot, ext=>$ext, by=>{%by}, pkg=>$pkg };
}

@res = sort { $b->{tot} <=> $a->{tot} } @res;
for my $r (@res[0..29]) {
  last unless $r;
  my $rel = $r->{file}; $rel =~ s{^\Q$root\E/}{};
  printf("%5d tot %5d ext  %-6s %-38s %s:%d\n", $r->{tot}, $r->{ext}, ($r->{method}?"method":"func"), $r->{name}, $rel, $r->{line});
}
EOF
